arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fix: Resolve scoped service via IServiceScopeFactory to avoid captive dependency.
// .NET 9 enables ValidateScopes in development, which throws for scoped services
// resolved from the root provider inside a singleton factory.
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IServiceScopeFactory>()));
// Fix: Use SocketsHttpHandler directly. .NET 9 HttpClientFactory now uses
// SocketsHttpHandler as the default primary handler; casting to HttpClientHandler throws.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });
// Fix: Explicitly allowlist non-sensitive headers for Trace-level logging.
// .NET 9 redacts all header values by default in HttpClientFactory logs.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" && h != "X-Correlation-Id" && h != "Cache-Control"));
// Fix: Forwarded Headers middleware now ignores X-Forwarded-* from unknown proxies.
// Add your reverse proxy address to KnownProxies or KnownNetworks.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: Replace with your actual proxy IP or network range.
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

